import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADRs and Final Implementation Principles","description":"","frontmatter":{"title":"ADRs and Final Implementation Principles"},"headers":[],"relativePath":"guide/adr-principles.md","filePath":"guide/adr-principles.md","lastUpdated":1793382327000}`),a={name:`guide/adr-principles.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_17-adrs-architecture-decisions-that-must-be-recorded" tabindex="-1">17. ADRs: Architecture Decisions That Must Be Recorded <a class="header-anchor" href="#_17-adrs-architecture-decisions-that-must-be-recorded" aria-label="Permalink to “17. ADRs: Architecture Decisions That Must Be Recorded”">​</a></h1><p>The following decisions need to be archived as ADRs:</p><ol><li>Why Rust was chosen.</li><li>Why the first version uses external-process plugins.</li><li>Why JSON-RPC over stdio was chosen.</li><li>Why Resource + Dependency Graph was chosen.</li><li>Why the dependency graph is coordinated by the Core Engine.</li><li>Why action results must go through independent verification.</li><li>Why SQLite was chosen.</li><li>Why critical state must be persisted before recovery actions.</li><li>Why the notification system is decoupled from the recovery engine.</li><li>Why the Dashboard is disabled by default.</li><li>Why P0 implements only the Process and Exec Probes.</li><li>Why unauthorized high-risk network actions are not allowed.</li><li>Why unknown execution outcomes must not be retried directly.</li><li>Why ordinary dependency graph cycles are forbidden.</li></ol><p>An ADR must record the background, the decision, the alternatives, the pros and cons, and the follow-up impact.</p><ol start="15"><li>Why the core maintains an internal integration toolbox (HTTP/RPC/SSH/probing primitives) and plugins are only the rule layer.</li></ol><p><strong>Background</strong>: as probing and recovery actions come to cover HTTP, RPC, SSH, service control and other transports/protocols, if every plugin implements its own transport, the security hardening (TLS verification, SSRF protection, SSH host-key verification, timeout/retry/cancellation, credential-safe reads) is diluted across N implementations and cannot be uniformly enforced.</p><p><strong>Decision</strong>: the core converges a set of &quot;internal integration tools&quot; as capability executors (HTTP client, RPC client, SSH client, process/service/disk/network-connectivity probes, controlled command execution, reboot control), declared via Capability + OperationParams. Plugins and built-in capabilities share one dispatch table: built-in capabilities execute in-process in the core, plugin-declared capabilities execute in the plugin subprocess. Plugins no longer implement transports themselves; they provide capability declarations and rule logic (targets, parameters, decisions, verification).</p><p><strong>Alternatives</strong>: keep plugins self-contained, each implementing its own transport. Drawbacks: duplicated transports, hardening easily bypassed, larger plugin footprint and attack surface.</p><p><strong>Pros and cons</strong>: hardening happens once, in one place; unified semantics (timeout/cancel/budget/audit); thinner plugins. The cost is that the core&#39;s tool surface must be maintained, and plugin freedom shrinks (no arbitrary custom protocols).</p><p><strong>Follow-up impact</strong>: P2 platform adapters (systemd/launchd/SCM, network interface/route/DNS) register as tool executors in the same registry; the Webhook notification channel reuses the toolbox HTTP client (with SSRF protection); the Python outbound bindings expose tool calls, not arbitrary execution.</p><hr><h1 id="_18-final-implementation-principles" tabindex="-1">18. Final Implementation Principles <a class="header-anchor" href="#_18-final-implementation-principles" aria-label="Permalink to “18. Final Implementation Principles”">​</a></h1><p>Custos&#39;s success criterion is not how many kinds of services it can monitor, but whether, when a real failure strikes, it can correctly judge dependencies, execute appropriate recovery actions, verify the results, and leave a complete record.</p><p>The whole system should follow:</p><p><strong>Resources describe objects, dependencies describe preconditions, plugins provide capabilities, policies decide actions, the core engine coordinates execution, verification judges results, persistence preserves facts, notification delivers events, and the Dashboard provides optional display.</strong></p><p>Phase one must first get the core recovery loop, dependency semantics, persistence and failure handling right. Windows network recovery, proxies, Cloudflare Tunnel, OpenClash and other platform capabilities are added gradually afterwards.</p><p>Do not implement every plugin at once, and do not build a complex Dashboard or plugin marketplace ahead of time.</p><p>Prove the architecture with the minimal but complete recovery loop first, then expand based on the failures that real deployments cannot yet handle.</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};